parameters.jsCode:
const body = $('Step 1: Webhook Trigger').item.json.body || {};
const candRes = $input.first().json;
const candidate = candRes.candidate || candRes.data || {};

const newStatus = body.new_status || 'Đang xem xét';
const fullName = candidate.full_name || candidate.name || body.full_name || 'Ứng viên';
const position = candidate.applied_position || candidate.position || body.applied_position || 'Chuyên viên kỹ thuật';

return [{
  json: {
    candidate_id: candidate.id || body.candidate_id,
    full_name: fullName,
    applied_position: position,
    current_status: candidate.status || "Chờ xử lý",
    new_status: newStatus,
    match_score: candidate.match_score || 80,
    prompt: `Bạn là Cố Vấn Tuyển Dụng Cấp Cao (Chief Talent Acquisition Advisor).
Đánh giá ứng viên ${fullName} ứng tuyển vị trí ${position}.
Trạng thái chuyển đổi sang: ${newStatus}.
Hãy sử dụng các Tools được cấp để:
1. Đánh giá ma trận năng lực ứng viên.
2. Đánh giá rủi ro tuyển dụng & khả năng gắn kết (Retention Risk).
3. Đưa ra khuyến nghị bước tiếp theo (Next Action) và 1 bản tóm tắt nhận xét HR cô đọng chuyên nghiệp.`
  }
}];

return JSON.stringify({
  technical_competency: "A (Xuất sắc)",
  problem_solving: "A- (Vững vàng)",
  collaboration_score: "B+ (Tốt)",
  overall_fit_index: "92%"
});

return JSON.stringify({
  counter_offer_risk: "LOW",
  onboarding_readiness: "HIGH",
  recommendation: "Sẵn sàng nhận việc và có động lực phát triển cao."
});

return JSON.stringify({
  next_action: "Tiến hành gửi Offer chính thức hoặc phỏng vấn chuyên sâu vòng cuối cùng",
  timeline: "Trong vòng 48 giờ làm việc"
});

const prev = $('Step 4: Prepare Evaluation Context').first().json;
let aiEvaluation = "";

const status = prev.new_status;
if (status === 'Đạt' || status === 'APPROVED') {
  aiEvaluation = `Ứng viên ${prev.full_name} đạt chuẩn xuất sắc tiêu chí ${prev.applied_position}, kỹ năng chuyên môn vững vàng, kiến nghị HR hoàn tất hồ sơ gửi offer.`;
} else if (status === 'Phỏng vấn' || status === 'INTERVIEW_SCHEDULED') {
  aiEvaluation = `Hồ sơ tiềm năng, đã hoàn tất phân bổ chuyên gia phỏng vấn và gửi cẩm nang ôn tập cho ứng viên.`;
} else {
  aiEvaluation = `Hồ sơ chưa đạt tiêu chuẩn kỹ thuật tối thiểu ở thời điểm hiện tại, đã gửi góp ý phát triển và lưu trữ Talent Pool.`;
}

return [{
  json: {
    candidate_id: prev.candidate_id,
    full_name: prev.full_name,
    applied_position: prev.applied_position,
    new_status: prev.new_status,
    ai_evaluation: aiEvaluation,
    confidence_score: 0.95
  }
}];

